import { mkdir, readFile, writeFile } from 'node:fs/promises';

const sourceFiles = [
  'src/core/EventBus.js',
  'src/core/GameState.js',
  'src/battle/Unit.js',
  'src/battle/ActionResolver.js',
  'src/battle/CTBEngine.js',
  'src/data/abilityData.js',
  'src/data/partyData.js',
  'src/data/bossData.js',
  'src/ui/MessageWindow.js',
  'src/battle/BattleManager.js',
  'src/ui/BattleUI.js',
  'src/ui/IntermissionUI.js',
  'src/main.js',
];

const chunks = [];

for (const file of sourceFiles) {
  const source = await readFile(file, 'utf8');
  const bundled = source
    .replace(/^import\s+.+?;\r?\n/gm, '')
    .replace(/^export\s+\{[^}]+\};?\r?\n/gm, '')
    .replace(/^export\s+(?=(?:class|const|function)\s)/gm, '');

  chunks.push(`// ---- ${file} ----\n${bundled.trim()}\n`);
}

const output = `// Generated by scripts/build-bundle.mjs.\n// This classic script also works when index.html is opened via file://.\n(() => {\n'use strict';\n\n${chunks.join('\n')}\n})();\n`;

await mkdir('.', { recursive: true });
await writeFile('app.js', output, 'utf8');
